interface ResourceRec {
  id: string;
  type: ResourceType;
  name: string;
  open: Array<[string, string]>;
  prepMinutes: number; // 预约前准备分钟：实际占用自活动开始向前扩张；非负安全整数，旧文件缺省为 0
  teardownMinutes: number; // 结束后整理分钟：实际占用自活动结束向后扩张；非负安全整数，旧文件缺省为 0
}

