2837	async function cmdAddWaitlist(args: string[]): Promise<void> {
2838	  const {values, positionals} = parseFlags(args, ['resource', 'start', 'end'], ['resource']);
2839	  if (positionals.length > 0) throw new UsageError(`add-waitlist 不接受位置参数: ${positionals.join(' ')}`);
2840	
2841	  const resourceArgs = values.get('resource');
2842	  if (!resourceArgs || resourceArgs.length === 0) throw new UsageError('至少需要一个 --resource');
2843	  const startRaw = requireFlag(values, 'start');
2844	  const endRaw = requireFlag(values, 'end');
2845	
2846	  const file = activeDataFile;
2847	  const store = await loadStoreForWrite(file);
2848	
2849	  const ids = resolveResourceIds(store, resourceArgs);
2850	  const startMin = parseDateTime(startRaw, '候补开始时间');
2851	  const endMin = parseDateTime(endRaw, '候补结束时间');
