2865	    resourceIds: ids,
2866	    start: startRaw,
2867	    end: endRaw,
2868	    status: 'waiting',
2869	    seq,
2870	  });
2871	  await saveStore(file, store);
2872	  console.log(`已登记固定时段候补 ${id}（登记序号 ${seq}，不占用资源）`);
