2878	// 解析正整数分钟时长（不接受 0、负数、小数与前导零）
2879	function parseDurationMinutes(raw: string): number {
2880	  if (!/^[1-9]\d*$/.test(raw)) {
2881	    throw new BizError(`时长非法: “${raw}”，必须是正整数分钟`);
2882	  }
2883	  return Number(raw);
2884	}
2885	
2886	// 解析“窗口开始/窗口结束”（弹性候补窗口、候选组合查询窗口共用；label 用于报错定位）
2887	function parseFlexWindow(
2888	  value: string,
2889	  label = '弹性窗口',
2890	): {start: string; end: string; startMin: number; endMin: number} {
2891	  const parts = String(value ?? '').split('/');
2892	  if (parts.length !== 2 || parts[0] === '' || parts[1] === '') {
2893	    throw new BizError(
2894	      `${label}格式非法: “${value}”，应为 窗口开始/窗口结束（YYYY-MM-DDTHH:mm/YYYY-MM-DDTHH:mm）`,
2895	    );
2896	  }
2897	  const start = parts[0];
2898	  const end = parts[1];
2899	  const startMin = parseDateTime(start, `${label}开始时间`);
2900	  const endMin = parseDateTime(end, `${label}结束时间`);
2901	  if (endMin <= startMin) {
2902	    throw new BizError(`${label}结束时间必须晚于开始时间: “${value}”，允许跨日`);
2903	  }
2904	  return {start, end, startMin, endMin};
2905	}
2906	
2907	// 渲染一组分钟区间（附分钟数），按开始时间排序；空集给明确提示
2908	function renderMinuteSegments(segments: Array<[number, number]>, indent: string): string[] {
2909	  if (segments.length === 0) return [`${indent}（无）`];
2910	  return segments.map(([s, e]) => {
2911	    const startRaw = formatDateTime(s);
2912	    const endRaw = formatDateTime(e);
2913	    return `${indent}- ${startRaw} → ${endRaw}（${e - s} 分钟）`;
2914	  });
2915	}
