3489	async function loadFlexManifest(file: string): Promise<unknown> {
3490	  let text: string;
3491	  try {
3492	    text = await readFile(file, 'utf8');
3493	  } catch (err) {
3494	    throw new BizError(`无法读取预约清单 ${file}: ${(err as Error).message}`);
3495	  }
3496	  try {
3497	    return JSON.parse(text);
3498	  } catch (err) {
3499	    throw new BizError(`预约清单 ${file} 已损坏，不是合法 JSON：${(err as Error).message}`);
3500	  }
3501	}
3502	
3503	// 清单结构（与业务数据无关的纯类型校验）；返回逐项原始记录
3504	function parseFlexPlanShape(raw: unknown, file: string): {
3505	  items: Array<Record<string, unknown>>;
3506	  relations: Array<Record<string, unknown>>;
3507	} {
3508	  if (typeof raw !== 'object' || raw === null || Array.isArray(raw)) {
3509	    throw new BizError(`预约清单 ${file} 内容非法：顶层必须是对象，形如 {"items": [...]}`);
3510	  }
3511	  const o = raw as Record<string, unknown>;
3512	  for (const k of Object.keys(o)) {
3513	    if (k !== 'items' && k !== 'relations') {
3514	      throw new BizError(`预约清单 ${file} 内容非法：存在未知字段 “${k}”，只允许 items、relations`);
3515	    }
3516	  }
3517	  if (!Array.isArray(o.items)) {
3518	    throw new BizError(`预约清单 ${file} 内容非法：items 必须是非空数组`);
3519	  }
3520	  const items = o.items as unknown[];
3521	  if (items.length === 0) throw new BizError(`预约清单 ${file} 为空：items 至少包含一项预约请求`);
3522	
3523	  // 附加项间关系（可省略或为空数组：省略或为空保持无关系的原行为）。
3524	  // 结构在此做与业务数据无关的纯类型校验；序号范围、自指、重复与有向环
3525	  // 需在知道项数后由 parseFlexRelations 再校验。
3526	  const relationRecords: Array<Record<string, unknown>> = [];
3527	  if (o.relations !== undefined) {
3528	    if (!Array.isArray(o.relations)) {
3529	      throw new BizError(`预约清单 ${file} 内容非法：relations 必须是数组（可省略或为空）`);
3530	    }
3531	    const relProblems: string[] = [];
3532	    (o.relations as unknown[]).forEach((rel, ri) => {
3533	      const at = `第 ${ri + 1} 条关系`;
3534	      if (typeof rel !== 'object' || rel === null || Array.isArray(rel)) {
3535	        relProblems.push(`${at} 必须是对象`);
