function formatResourceIds(store: Store, ids: string[]): string {
  return ids
    .map((id) => {
      const r = store.resources.find((x) => x.id === id);
      return r ? `${id}（${r.name}）` : id;
    })
    .join('、');
}

// 校验请求中的资源标识：去重、检查存在性；返回按标识排序的集合
function resolveResourceIds(store: Store, rawIds: string[]): string[] {
  const problems: string[] = [];
  const seen = new Set<string>();
  const dupes: string[] = [];
  for (const id of rawIds) {
    if (seen.has(id)) {
      if (!dupes.includes(id)) dupes.push(id);
    }
    seen.add(id);
  }
  if (dupes.length > 0) problems.push(`资源重复指定: ${dupes.join('、')}`);

  const unknown = [...seen].filter((id) => !store.resources.some((r) => r.id === id)).sort();
  if (unknown.length > 0) problems.push(`未知资源标识: ${unknown.join('、')}`);

  if (problems.length > 0) throw new BizError(problems.join('\n'));
  return [...seen].sort();
}

function openSegmentsOf(r: ResourceRec): Array<[number, number]> {
  return mergeIntervals(
    r.open.map(
      ([s, e]) =>
        [parseDateTime(s, '开放区间开始时间'), parseDateTime(e, '开放区间结束时间')] as [number, number],
    ),
  );
}

// 从连续区间中扣除一段停用（左闭右开），返回剩余连续区间
function subtractSegments(
  segments: Array<[number, number]>,
  cuts: Array<[number, number]>,
): Array<[number, number]> {
  let result = segments;
  for (const [cs, ce] of mergeIntervals(cuts)) {
    const next: Array<[number, number]> = [];
    for (const [s, e] of result) {
      if (ce <= s || e <= cs) {
        next.push([s, e]);
        continue;
      }
      if (s < cs) next.push([s, cs]);
      if (ce < e) next.push([ce, e]);
    }
    result = next;
  }
  return result;
}

// 某资源的有效停用记录（按开始时间、标识排序）
function activeClosuresOf(store: Store, resourceId: string): ClosureRec[] {
  return store.closures
    .filter((c) => c.resourceId === resourceId && c.status === 'active')
    .sort(
      (a, b) =>
        parseDateTime(a.start, '停用开始时间') - parseDateTime(b.start, '停用开始时间') ||
        a.id.localeCompare(b.id),
    );
}

// 实际可用时间：原开放区间合并后，扣除该资源全部有效停用区间的并集（原开放记录保留）。
// extraCuts 供“停用 + 本地弹性改期清单”同次提交使用：拟登记的停用尚未落盘，
// 求解时须把它与既有有效停用一并扣除（调用方保证为已合并的左闭右开区间）。
function availableSegmentsOf(
  store: Store,
  r: ResourceRec,
  extraCuts: ReadonlyArray<[number, number]> = [],
): Array<[number, number]> {
  const cuts = activeClosuresOf(store, r.id).map(
    (c) =>
      [parseDateTime(c.start, '停用开始时间'), parseDateTime(c.end, '停用结束时间')] as [number, number],
  );
  return subtractSegments(openSegmentsOf(r), [...cuts, ...extraCuts]);
}

interface CoverageGap {
  id: string;
  r: ResourceRec;
  occStart: number; // 该资源上的实际占用开始（活动开始减准备）
  occEnd: number; // 该资源上的实际占用结束（活动结束加整理）
  outOfRange: boolean; // 实际占用越出 0001-9999 年范围
  closures: ClosureRec[]; // 与该实际占用重叠的相关有效停用（按开始时间、标识排序）
}

// 找出实际占用不能被实际可用时间完整覆盖的资源。
// 活动 [startMin, endMin) 在每个资源上的实际占用分别为
// [startMin-准备, endMin+整理)（左闭右开，各资源独立扩张，不取最大缓冲）；
// extraCutsById 为按资源给出的附加扣除区间（拟登记但尚未落盘的停用），同样计入。
// 实际占用越出四位年份范围（0001-01-01T00:00 前或 9999-12-31T24:00 后）也判为不足。
function findCoverageGaps(
  store: Store,
  ids: string[],
  startMin: number,
  endMin: number,
  extraCutsById?: ReadonlyMap<string, ReadonlyArray<[number, number]>>,
): CoverageGap[] {
  const gaps: CoverageGap[] = [];
  for (const id of ids) {
    const r = store.resources.find((x) => x.id === id)!;
    const [occStart, occEnd] = occupancyOn(r, startMin, endMin);
    const outOfRange = occStart < MIN_MINUTE || occEnd > MAX_MINUTE_EXCLUSIVE;
    const extra = extraCutsById?.get(id) ?? [];
    const covered =
      !outOfRange && isFullyCovered(availableSegmentsOf(store, r, extra), occStart, occEnd);
    if (covered) continue;
    const closures = activeClosuresOf(store, id).filter((c) => {
      const cs = parseDateTime(c.start, '停用开始时间');
      const ce = parseDateTime(c.end, '停用结束时间');
      return cs < occEnd && occStart < ce;
    });
    gaps.push({id, r, occStart, occEnd, outOfRange, closures});
  }
  return gaps;
}

// 开放不足资源的统一展示：资源行、实际占用区间与相关有效停用（标识与时间）
function gapLines(gaps: CoverageGap[], indent: string): string[] {
  const lines: string[] = [];
  for (const g of gaps) {
    lines.push(`${indent}- ${g.id}（${g.r.name}）`);

