  end: string; // 原请求结束时间；弹性项为窗口结束
  durationMinutes?: number; // 仅弹性项：所需连续时长（正整数分钟，不超过窗口长度）
  status: WaitlistStatus;
  seq: number; // 登记序号：1 基，列表与处理均按此稳定排序，重启后仍在
