// 原请求的统一展示：固定项给原时段；弹性项给窗口与所需连续时长
function renderWaitlistRequest(w: WaitlistRec): string {
  if (w.kind === 'flexible') {
    return `弹性窗口 ${w.start} → ${w.end}（所需连续时长 ${w.durationMinutes} 分钟）`;
  }
  return `固定时段 ${w.start} → ${w.end}`;
}

