    // 没有可兑现项也成功：明确说明，不保存、不改变记录或计数
    console.log(
      `候补处理完成：本轮处理 ${waiting.length} 项等待候补，没有可兑现项` +
        '（固定项开放不足或仍有冲突；弹性项窗口内无足够长的共同空闲），全部继续等待；记录、占用与标识计数不变。',
    );
    for (const w of blocked) {
      console.log(renderBlocked(store, w, fromWaitlistByBooking));
    }
    return;
  }

