  // (b) 两组同候选：同一 08:00 两组合 [R2,R3]/[R3,R2]，取字典序 [R2,R3]
  addFlexGroup(df, ['R0003,R0002', 'R0002,R0003'], '2026-10-12T08:00/2026-10-12T12:00', '60', 'W0002 乱序登记');

  const r = ok(df, ['process-waitlist'], '按序兑现两项');
