1919	function parseFlags(args: string[], allowed: string[], multi: string[] = []): ParsedFlags {
1920	  const allowedSet = new Set(allowed);
1921	  const multiSet = new Set(multi);
1922	  const values = new Map<string, string[]>();
1923	  const positionals: string[] = [];
1924	
1925	  const takeValue = (key: string, inline: string | undefined, index: number): [string, number] => {
1926	    if (inline !== undefined) return [inline, index];
1927	    const v = args[index + 1];
1928	    if (v === undefined || v.startsWith('-')) {
1929	      throw new UsageError(`选项 --${key} 缺少值`);
1930	    }
1931	    return [v, index + 1];
1932	  };
1933	
1934	  for (let i = 0; i < args.length; i++) {
1935	    const a = args[i];
1936	    if (a.startsWith('--')) {
1937	      let key: string;
1938	      let inline: string | undefined;
1939	      const eq = a.indexOf('=');
1940	      if (eq >= 0) {
1941	        key = a.slice(2, eq);
1942	        inline = a.slice(eq + 1);
1943	      } else {
1944	        key = a.slice(2);
1945	      }
1946	      if (!allowedSet.has(key)) throw new UsageError(`未知选项: --${key}`);
1947	      let v: string;
1948	      [v, i] = takeValue(key, inline, i);
1949	      if (v === '') throw new UsageError(`选项 --${key} 的值不能为空`);
1950	      if (!multiSet.has(key) && values.has(key)) {
1951	        throw new UsageError(`选项 --${key} 只能指定一次`);
1952	      }
1953	      const list = values.get(key) ?? [];
1954	      list.push(v);
1955	      values.set(key, list);
1956	    } else if (a.startsWith('-') && a !== '-') {
1957	      throw new UsageError(`未知参数: ${a}`);
1958	    } else {
1959	      positionals.push(a);
1960	    }
1961	  }
1962	  return {values, positionals};
1963	}
1964	
